// checks.js: the trainer's helper. Students do NOT edit this file.
// It loads each step file, tests it, and tells final.js which steps are done.
const path = require("path");

const APP = "Marks Analyzer";
const TOTAL = 10;
const STEPS = [
  { n: 1, file: './step01_header', title: 'Page title', day: 2, check: (f) => String(f()).includes('<h1') },
  { n: 2, file: './step02_name_box', title: 'Name input box', day: 2, check: (f) => String(f()).includes('name="name"') },
  { n: 3, file: './step03_marks_box', title: 'Marks input box', day: 2, check: (f) => String(f()).includes('name="marks"') },
  { n: 4, file: './step04_add_button', title: 'Add button', day: 2, check: (f) => String(f()).includes('<button') },
  { n: 5, file: './step05_show_list', title: 'Show each student in the list', day: 2, check: (f) => String(f({name:'Ravi',marks:90})).includes('Ravi') && String(f({name:'Ravi',marks:90})).includes('90') },
  { n: 6, file: './step06_total', title: 'Total marks', day: 2, check: (f) => f([{name:'A',marks:50},{name:'B',marks:70}]) === 120 },
  { n: 7, file: './step07_grade', title: 'Grade with if / else', day: 2, check: (f) => f(95) === 'A' && f(80) === 'B' && f(65) === 'C' && f(30) === 'D' },
  { n: 8, file: './step08_topper', title: 'Find the topper', day: 2, check: (f) => f([{name:'A',marks:50},{name:'B',marks:90},{name:'C',marks:70}]).name === 'B' },
  { n: 9, file: './step09_delete', title: 'Delete a student', day: 2, check: (f) => (L => { f(L, 1); return L.map(x => x.name).join() === 'A,C'; })([{name:'A',marks:1},{name:'B',marks:2},{name:'C',marks:3}]) },
  { n: 10, file: './step10_footer', title: 'Footer with your name', day: 2, check: (f) => String(f()).includes('<footer') },
];

function load(n) {
  const s = STEPS[n - 1];
  const info = { n: s.n, title: s.title, file: s.file.slice(2) + ".js", day: s.day, f: null, status: "todo", err: "" };
  try {
    const full = require.resolve(path.join(__dirname, s.file));
    delete require.cache[full];
    const f = require(full);
    if (typeof f !== "function") throw new Error("module.exports was changed. Undo your change at the bottom of the file.");
    info.f = f;
    info.status = s.check(f) ? "done" : "todo";
  } catch (e) {
    info.status = "error";
    const m = String(e.stack || "").match(new RegExp(s.file.slice(2) + "\\.js:(\\d+)"));
    info.err = e.name + ": " + e.message + (m ? " (line " + m[1] + ")" : "");
  }
  return info;
}

function loadAll() {
  const all = {};
  for (let n = 1; n <= TOTAL; n++) all[n] = load(n);
  return all;
}

function run(n) {
  const s = load(n);
  console.log();
  if (s.status === "done") {
    console.log("  ✅  Step " + n + " done: " + s.title);
    console.log(n < TOTAL ? "      Refresh the browser page to see it. Then open step " + String(n + 1).padStart(2, "0") + "." : "      🎉 All steps finished!");
  } else if (s.status === "error") {
    console.log("  🔴  Step " + n + " has an error: " + s.err);
    console.log('      Check spelling, quotes " ", brackets ( ) { } and the ; at the end.');
  } else {
    console.log("  ❌  Step " + n + " not done yet: " + s.title);
    console.log("      Open " + s.file + ", type the line shown in the comment, save (Ctrl + S) and run this again.");
  }
  let done = 0;
  for (let k = 1; k <= TOTAL; k++) if (load(k).status === "done") done++;
  console.log("      Progress: " + done + " / " + TOTAL + " steps done");
  console.log();
}

module.exports = { APP, TOTAL, load, loadAll, run };
